    public java.util.Map<String, Object> debugImageMatching(Long paintingId, MultipartFile userImage) {
        java.util.Map<String, Object> result = new java.util.HashMap<>();
        
        try {
            // Get painting
            Painting painting = paintingRepository.findById(paintingId)
                    .orElseThrow(() -> new RuntimeException("Painting not found"));

            result.put("paintingId", paintingId);
            result.put("paintingTitle", painting.getTitle());
            result.put("imageRecognitionKey", painting.getImageRecognitionKey());
            result.put("userImageSize", userImage.getSize());
            result.put("userImageContentType", userImage.getContentType());

            if (painting.getImageRecognitionKey() == null || painting.getImageRecognitionKey().isEmpty()) {
                result.put("error", "No imageRecognitionKey configured");
                return result;
            }

            String referenceImagePath = "paintings/" + painting.getImageRecognitionKey() + ".jpg";
            result.put("referenceImagePath", referenceImagePath);

            // Try to download reference image
            String localReferencePath;
            try {
                localReferencePath = minioStorageService.downloadImageToTemp(referenceImagePath);
                result.put("referenceImageDownloaded", true);
                result.put("localReferencePath", localReferencePath);
            } catch (Exception e) {
                result.put("referenceImageDownloaded", false);
                result.put("downloadError", e.getMessage());
                return result;
            }

            try {
                // Perform matching
                double score = imageMatchingService.compareImages(userImage, localReferencePath);
                boolean isMatch = imageMatchingService.isMatchValid(score);

                result.put("confidenceScore", score);
                result.put("isMatch", isMatch);
                result.put("threshold", 0.65);
                result.put("message", isMatch ? "Images match!" : "Images do not match");

            } finally {
                minioStorageService.deleteTempFile(localReferencePath);
            }

        } catch (Exception e) {
            result.put("error", e.getMessage());
            result.put("stackTrace", e.getClass().getName());
        }

        return result;
    }

